-- Gyeon + Nanolex catalog reload, generated from the supplier price-list PDFs
-- (ListaPrecios/). Prices include IVA. Cost is 0 and stock is 99 by design:
-- the store has no link to physical inventory, so stock is an availability flag
-- (99 = available, 0 = sold out / on request) changed only by an administrator.
-- Products: 202. Variants: 285.
BEGIN;

-- Remove previous Gyeon/Nanolex rows (variants, specs, images and steps cascade).
DELETE FROM product WHERE brand_id IN (SELECT id FROM brand WHERE nombre IN ('Gyeon','Nanolex'));



-- Every presentation starts as available.
UPDATE product_variant SET stock = 99, updated_at = now() WHERE stock <> 99;

COMMIT;
